/* Signature Catalan Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jordimont": "From Jordi + mont (mountain).", "Montserratina": "From Montserrat + -ina.", "Josepmar": "From Josep + mar (sea).", "Annamuntanya": "From Anna + muntanya (mountain).", "Pereblau": "From Pere + blau (blue).", "Nuriacel": "From Nuria + cel (sky).", "Puigmar": "Signature surname: 'sea hill'.", "Ferrercel": "Signature surname: 'sky smith'.", "Vidalblau": "Signature surname.", "Serramunt": "Signature surname: 'mountain range'."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jordimont';
console.log(lookup(q));

